    h=len(g);w=len(g[0]);seen=set();out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==0 or (r,c) in seen: continue
            col=g[r][c];st=[(r,c)];seen.add((r,c));pix=[]
            while st:
                x,y=st.pop();pix.append((x,y))
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if dr==0 and dc==0: continue
                        if (not diag) and abs(dr)+abs(dc)!=1: continue
                        nr,nc=x+dr,y+dc
                        if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and g[nr][nc]==col:
                            seen.add((nr,nc));st.append((nr,nc))
